/* @lc app=leetcode id=3447 lang=kotlin */ class Solution { fun assignElements(groups: IntArray, elements: IntArray): IntArray = IntArray(100001) { Int.MAX_VALUE }.also { b -> HashSet<Int>().let { seen -> elements.indices.filter { seen.add(elements[it]) }.forEach { j -> (elements[j]..100000 step elements[j]).forEach { m -> b[m] = minOf(b[m], j) } } } }.let { b -> IntArray(groups.size) { b[groups[it]].let { v -> if (v == Int.MAX_VALUE) -1 else v } } } }